constexpr std::size_t EntryCount = sizeof(Entries) / sizeof(Entries[0]);

inline const Entry* find(const char* key) {
    if (!key) return nullptr;
    std::size_t begin = 0, end = EntryCount;
    while (begin < end) {
        const std::size_t middle = begin + (end - begin) / 2;
        const int order = std::strcmp(key, Entries[middle].key);
        if (order == 0) return &Entries[middle];
        if (order < 0) end = middle;
        else begin = middle + 1;
    }
    return nullptr;
}

inline const char* get(const char* key, bool russian) {
    const auto* entry = find(key);
    return entry ? (russian ? entry->ru : entry->en) : nullptr;
}

// Godot String.length counts Unicode code points, including spaces and newlines.
inline unsigned characterCount(const char* text) {
    unsigned count = 0;
    if (text) for (; *text; ++text) count += (static_cast<unsigned char>(*text) & 0xc0u) != 0x80u;
    return count;
}

